import{_ as e,c as a,o as r,a2 as s}from"./chunks/framework.DE3IEV19.js";const i="/assets/post_2025_11_05.BleYo1P9.mp4",n="/assets/Spectogram%20channel55.Cdoja35s.png",o="/assets/countmonitor.IupTjiz9.jpeg",l="/assets/blink.tVhebUL8.png",d="/assets/gobyappear.C7HEPxYQ.jpeg",h="/assets/hours.CEcP-5uY.png",c="/assets/flowers.2G81LdzH.jpeg",p="/assets/siren.DlUwm9Nr.jpeg",g="/assets/monitor%20id.CXqNH0eE.png",u="/assets/G5CbTQPXYAAo_WN._YJN56Yx.jpeg",m="/assets/snakech.Cq6B0817.jpeg",x="/assets/streetwse.DkG4CFX-.png",b="/assets/frogs.Cjbbl9qN.jpeg",v="/assets/hamlet2.Bsnde8jn.png",w=JSON.parse('{"title":"Neuko.ai TV Portal (Post #9) - First ARG Treasure Hunt Debrief","description":"Post #9 revealed the Neuko.ai TV portal. This debrief documents the channel hunt, hidden spectrogram clue, archives_x messages, key.txt, seed phrase, and the final on-chain reward.","frontmatter":{"title":"Neuko.ai TV Portal (Post #9) - First ARG Treasure Hunt Debrief","description":"Post #9 revealed the Neuko.ai TV portal. This debrief documents the channel hunt, hidden spectrogram clue, archives_x messages, key.txt, seed phrase, and the final on-chain reward.","date":"2025-12-16","author":"@DendiRedemption","tags":["ARG","NeukoAI","Treasure Hunt","Website","TV Portal","Puzzle"],"draft":false},"headers":[],"relativePath":"transmissions/posts/post-9.md","filePath":"transmissions/posts/post-9.md"}'),_={name:"transmissions/posts/post-9.md"};function f(k,t,y,T,E,C){return r(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="neuko-ai-tv-portal-post-9-first-arg-treasure-hunt-debrief" tabindex="-1">Neuko.ai TV Portal (Post #9) - First ARG Treasure Hunt Debrief <a class="header-anchor" href="#neuko-ai-tv-portal-post-9-first-arg-treasure-hunt-debrief" aria-label="Permalink to &quot;Neuko.ai TV Portal (Post #9) - First ARG Treasure Hunt Debrief&quot;">​</a></h1><blockquote><p><strong>Debrief by <a href="https://x.com/DendiRedemption" target="_blank" rel="noreferrer">@DendiRedemption</a></strong></p></blockquote><p><strong>Post #9 (Nov 5, 2025):</strong> <a href="https://x.com/neukoai/status/1986152753412919577" target="_blank" rel="noreferrer">https://x.com/neukoai/status/1986152753412919577</a><br><strong>Caption:</strong> <a href="https://www.neuko.ai/" target="_blank" rel="noreferrer">https://www.neuko.ai/</a></p><hr><h2 id="the-post" tabindex="-1">The Post <a class="header-anchor" href="#the-post" aria-label="Permalink to &quot;The Post&quot;">​</a></h2><p><video controls width="100%"><source src="'+i+'" type="video/mp4"></video></p><p>Post #9 is the moment the hunt moved from X into the <strong>website portal</strong>.</p><hr><h2 id="website-portal-pin-→-tv-interface" tabindex="-1">Website Portal: PIN → TV Interface <a class="header-anchor" href="#website-portal-pin-→-tv-interface" aria-label="Permalink to &quot;Website Portal: PIN → TV Interface&quot;">​</a></h2><p>Opening <strong>neuko.ai</strong> revealed a TV with an <strong>Unlock</strong> section and a <strong>6-symbol PIN</strong> prompt.</p><p>The PIN was found in <a href="./post-7">Post 7</a>.</p><p>After entering the correct PIN, the site unlocked a <strong>TV interface</strong> with channels <strong>0–999</strong>.<br> Most channels were static, but a small set contained signals.</p><p>Credit: A lot of channel discovery was accelerated by <strong><a href="https://x.com/afkboom" target="_blank" rel="noreferrer">@afkboom</a></strong>, who used software to locate the active channels quickly.</p><p>Additional discovery credit goes to <strong><a href="https://x.com/thrax_nft" target="_blank" rel="noreferrer">@thrax_nft</a></strong>, who identified a disabled <strong>“Saint Juniper Research Campus”</strong> portal through console and source inspection. Extracted <code>.txt</code> files contained G*Boy logs detailing badge protocols, integrity checks, and operational directives, confirming the planned structure of badge distribution.</p><hr><h2 id="active-channels-at-the-time" tabindex="-1">Active Channels (at the time) <a class="header-anchor" href="#active-channels-at-the-time" aria-label="Permalink to &quot;Active Channels (at the time)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Channel</th><th>Title</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td>G*BOY</td></tr><tr><td style="text-align:right;">13</td><td>GAMBLIN!</td></tr><tr><td style="text-align:right;">28</td><td>The Crubtub</td></tr><tr><td style="text-align:right;">49</td><td>Real History</td></tr><tr><td style="text-align:right;">55</td><td>No Signal</td></tr><tr><td style="text-align:right;">77</td><td>archives_x_01.vid</td></tr><tr><td style="text-align:right;">86</td><td>archives_x_02.vid</td></tr><tr><td style="text-align:right;">101</td><td>archives_x_03.vid</td></tr><tr><td style="text-align:right;">200</td><td>Rabbits!</td></tr><tr><td style="text-align:right;">203</td><td>archives_x_04.vid</td></tr><tr><td style="text-align:right;">463</td><td>Moths!</td></tr><tr><td style="text-align:right;">550</td><td>archives_x_05.vid</td></tr><tr><td style="text-align:right;">717</td><td>archives_x_06.vid</td></tr><tr><td style="text-align:right;">777</td><td>archives_x_07.vid</td></tr></tbody></table><p>Channels with obvious broadcasts drew attention first (<strong>1, 13, 28, 49, 200, 463</strong>), but the <em>important</em> ones were the “quiet” archive channels and Channel 55:</p><p><strong>55, 77, 86, 101, 203, 550, 717, 777</strong></p><p>These could appear empty until you stayed long enough-then they revealed hidden messages.</p><hr><h2 id="channel-55-spectrogram-message" tabindex="-1">Channel 55 - Spectrogram Message <a class="header-anchor" href="#channel-55-spectrogram-message" aria-label="Permalink to &quot;Channel 55 - Spectrogram Message&quot;">​</a></h2><p>Channel 55 contained an audio clue with a spectrogram message:</p><p><img src="'+n+'" alt="Spectrogram decode — Channel 55"></p><p>Decoded message:</p><blockquote><p><strong>signals hide where the channels hum.</strong><br><strong>the key is underneath the static.</strong></p></blockquote><p>This was the “you’re close” signpost that pushed people to keep extracting.</p><hr><h2 id="the-archives-x-series-01–07" tabindex="-1">The <code>archives_x</code> Series (01–07) <a class="header-anchor" href="#the-archives-x-series-01–07" aria-label="Permalink to &quot;The `archives_x` Series (01–07)&quot;">​</a></h2><p>The channels below followed a consistent naming pattern: <code>archives_x_01.vid</code> → <code>archives_x_07.vid</code>.</p><ul><li>77 - archives_x_01.vid</li><li>86 - archives_x_02.vid</li><li>101 - archives_x_03.vid</li><li>203 - archives_x_04.vid</li><li>550 - archives_x_05.vid</li><li>717 - archives_x_06.vid</li><li>777 - archives_x_07.vid</li></ul><details><summary><strong>View archives_x frames (optional)</strong></summary><p><img src="'+o+'" alt="Count monitor"></p><p><img src="'+l+'" alt="Blink"></p><p><img src="'+d+'" alt="GBOY appears"></p><p><img src="'+h+'" alt="Hours"></p><p><img src="'+c+'" alt="Flowers"></p><p><img src="'+p+'" alt="Siren"></p><p><img src="'+g+'" alt="Monitor ID"></p><p><img src="'+u+'" alt="Numbers"></p><p><img src="'+m+'" alt="Snake channel"></p><p><img src="'+x+'" alt="Streetwse"></p><p><img src="'+b+'" alt="Frogs"></p><p><img src="'+v+'" alt="Hemlet Model"></p></details><p>Each archive video contained one or more messages that functioned like riddles.</p><hr><h2 id="hidden-messages-by-channel" tabindex="-1">Hidden Messages by Channel <a class="header-anchor" href="#hidden-messages-by-channel" aria-label="Permalink to &quot;Hidden Messages by Channel&quot;">​</a></h2><h3 id="channel-77-archives-x-01-vid" tabindex="-1">Channel 77 - archives_x_01.vid <a class="header-anchor" href="#channel-77-archives-x-01-vid" aria-label="Permalink to &quot;Channel 77 - archives_x_01.vid&quot;">​</a></h3><p>Related post: <a href="https://x.com/neukoai/status/1977763395408429229" target="_blank" rel="noreferrer">https://x.com/neukoai/status/1977763395408429229</a></p><ul><li>“EVERY SCREEN COUNTS”</li><li>“COUNT THE BLINKS OF THE MARK”</li></ul><h3 id="channel-86-archives-x-02-vid" tabindex="-1">Channel 86 - archives_x_02.vid <a class="header-anchor" href="#channel-86-archives-x-02-vid" aria-label="Permalink to &quot;Channel 86 - archives_x_02.vid&quot;">​</a></h3><p>Related post: <a href="https://x.com/neukoai/status/1979268208340406384" target="_blank" rel="noreferrer">https://x.com/neukoai/status/1979268208340406384</a></p><ul><li>“WHEN G304 ENTERS THE FRAME, MARK THE TIME.”</li></ul><h3 id="channel-101-archives-x-03-vid" tabindex="-1">Channel 101 - archives_x_03.vid <a class="header-anchor" href="#channel-101-archives-x-03-vid" aria-label="Permalink to &quot;Channel 101 - archives_x_03.vid&quot;">​</a></h3><p>Related post: <a href="https://x.com/neukoai/status/1980355518771392550" target="_blank" rel="noreferrer">https://x.com/neukoai/status/1980355518771392550</a></p><ul><li>“RECORD THE HOURS GIVEN.”</li><li>“COUNT THE BLOSSOMS TINTED PINK”</li></ul><h3 id="channel-203-archives-x-04-vid" tabindex="-1">Channel 203 - archives_x_04.vid <a class="header-anchor" href="#channel-203-archives-x-04-vid" aria-label="Permalink to &quot;Channel 203 - archives_x_04.vid&quot;">​</a></h3><p>Related post: <a href="https://x.com/neukoai/status/1981125805104312473" target="_blank" rel="noreferrer">https://x.com/neukoai/status/1981125805104312473</a></p><ul><li>“HOW MANY TIMES DOES THE SIREN BREAK THE SILENCE?”</li></ul><h3 id="channel-550-archives-x-05-vid" tabindex="-1">Channel 550 - archives_x_05.vid <a class="header-anchor" href="#channel-550-archives-x-05-vid" aria-label="Permalink to &quot;Channel 550 - archives_x_05.vid&quot;">​</a></h3><p>Related post: <a href="https://x.com/neukoai/status/1981740247504269582" target="_blank" rel="noreferrer">https://x.com/neukoai/status/1981740247504269582</a></p><ul><li>“CHECK THE MONITOR ID. KEEP THE FIRST PAIR OF NUMBERS.”</li><li>“FIND THE EMERGENCY CODE. KEEP ITS FIRST DIGIT ONLY.”</li></ul><h3 id="channel-717-archives-x-06-vid" tabindex="-1">Channel 717 - archives_x_06.vid <a class="header-anchor" href="#channel-717-archives-x-06-vid" aria-label="Permalink to &quot;Channel 717 - archives_x_06.vid&quot;">​</a></h3><p>Related post: <a href="https://x.com/neukoai/status/1982894878280569063" target="_blank" rel="noreferrer">https://x.com/neukoai/status/1982894878280569063</a></p><ul><li>“THE SNAKE STRIKES. RECORD ITS CHANNEL.”</li><li>“THE NUMBER BRIEFLY CARRYING STREETWISE.”</li></ul><h3 id="channel-777-archives-x-07-vid" tabindex="-1">Channel 777 - archives_x_07.vid <a class="header-anchor" href="#channel-777-archives-x-07-vid" aria-label="Permalink to &quot;Channel 777 - archives_x_07.vid&quot;">​</a></h3><p>Related post: <a href="https://x.com/neukoai/status/1984362507784351883" target="_blank" rel="noreferrer">https://x.com/neukoai/status/1984362507784351883</a></p><ul><li>“COUNT THE FROGS THAT FELL.”</li><li>“THE SIGNAL RUNS THROUGH HEMLET. RECORD ITS MODEL.”</li></ul><hr><h2 id="interpreting-the-riddles-→-12-numbers" tabindex="-1">Interpreting the Riddles → 12 Numbers <a class="header-anchor" href="#interpreting-the-riddles-→-12-numbers" aria-label="Permalink to &quot;Interpreting the Riddles → 12 Numbers&quot;">​</a></h2><p>There were <strong>7 archive channels</strong> with messages. The community realized these messages referenced the <strong>NeukoAI X videos released up to that date</strong>.</p><p>Each riddle resolved to a <strong>number</strong>. Across the full set, <strong>12 numbers</strong> were obtained-strongly suggesting a <strong>12-word seed phrase</strong>.</p><p>Extracted sequence: 9 10 17 7 24 4 12 8 14 15 25 2</p><hr><h2 id="underneath-the-static-key-txt" tabindex="-1">Underneath the Static: <code>key.txt</code> <a class="header-anchor" href="#underneath-the-static-key-txt" aria-label="Permalink to &quot;Underneath the Static: `key.txt`&quot;">​</a></h2><p>By inspecting the website network requests in devtools, a file was found:</p><p><a href="https://www.neuko.ai/key.txt" target="_blank" rel="noreferrer">https://www.neuko.ai/key.txt</a></p><p>It contained <strong>30 indexed words</strong>:</p><table tabindex="0"><thead><tr><th style="text-align:right;">#</th><th>Word</th><th style="text-align:right;">#</th><th>Word</th><th style="text-align:right;">#</th><th>Word</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td>ember</td><td style="text-align:right;">11</td><td>moss</td><td style="text-align:right;">21</td><td>synth</td></tr><tr><td style="text-align:right;">2</td><td>farm</td><td style="text-align:right;">12</td><td>focus</td><td style="text-align:right;">22</td><td>delta</td></tr><tr><td style="text-align:right;">3</td><td>static</td><td style="text-align:right;">13</td><td>gravel</td><td style="text-align:right;">23</td><td>echo</td></tr><tr><td style="text-align:right;">4</td><td>first</td><td style="text-align:right;">14</td><td>step</td><td style="text-align:right;">24</td><td>chicken</td></tr><tr><td style="text-align:right;">5</td><td>pulse</td><td style="text-align:right;">15</td><td>ready</td><td style="text-align:right;">25</td><td>square</td></tr><tr><td style="text-align:right;">6</td><td>fracture</td><td style="text-align:right;">16</td><td>lantern</td><td style="text-align:right;">26</td><td>coil</td></tr><tr><td style="text-align:right;">7</td><td>apple</td><td style="text-align:right;">17</td><td>crawl</td><td style="text-align:right;">27</td><td>fever</td></tr><tr><td style="text-align:right;">8</td><td>wife</td><td style="text-align:right;">18</td><td>glass</td><td style="text-align:right;">28</td><td>shrine</td></tr><tr><td style="text-align:right;">9</td><td>record</td><td style="text-align:right;">19</td><td>tether</td><td style="text-align:right;">29</td><td>token</td></tr><tr><td style="text-align:right;">10</td><td>deny</td><td style="text-align:right;">20</td><td>marrow</td><td style="text-align:right;">30</td><td>hush</td></tr></tbody></table><p>Mapping the 12 numbers to the word list produced the seed phrase:</p><p><strong>record deny crawl apple chicken first focus wife step ready square farm</strong></p><hr><h2 id="the-reward" tabindex="-1">The Reward <a class="header-anchor" href="#the-reward" aria-label="Permalink to &quot;The Reward&quot;">​</a></h2><p>The seed phrase unlocked the wallet: 71o2Q6oKUbTujnHmKXSSj2VD3EJZ3vUbwGTRN9yei32D</p><p>The treasure was <strong>3 Snake Badges</strong>, claimed in a timed race by <strong><a href="https://x.com/DendiRedemption" target="_blank" rel="noreferrer">@DendiRedemption</a></strong></p><hr><h2 id="extra-note-channel-717-message-correction" tabindex="-1">Extra Note (Channel 717 Message Correction) <a class="header-anchor" href="#extra-note-channel-717-message-correction" aria-label="Permalink to &quot;Extra Note (Channel 717 Message Correction)&quot;">​</a></h2><p>During the solve, Channel 717 originally displayed:</p><blockquote><p>“JPX SPEAK ONCE. NOT ITS CHANNEL.”</p></blockquote><p>This appeared to be an error and was later updated to:</p><blockquote><p><strong>“THE SNAKE STRIKES. RECORD ITS CHANNEL.”</strong></p></blockquote><hr><h2 id="related-posts" tabindex="-1">Related Posts <a class="header-anchor" href="#related-posts" aria-label="Permalink to &quot;Related Posts&quot;">​</a></h2><ul><li><a href="./post-7">Post #7: Channel Flipping</a> - PIN codes discovered</li><li><a href="./post-8">Post #8: Ultimatum</a> - Previous post</li><li><a href="./post-10">Post #10: Claymation</a> - Next post</li></ul><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="./../../website">Website Documentation</a> - Complete website details</li><li><a href="./../unsolved#treasure-trail-completion">Unsolved Mysteries</a> - Treasure trail status</li><li><a href="/community/overview#thrax_nft">Puzzle Contributors</a> - The solver</li></ul><p>[index0]</p>',85)])])}const N=e(_,[["render",f]]);export{w as __pageData,N as default};
